// Waypoints reales de Tuxtla Gutiérrez para Ruta 1 y Ruta 2
const ruta1Points = [
  { lat: 16.7450, lng: -93.1685, name: 'Terán' },
  { lat: 16.7535, lng: -93.1602, name: 'UNACH Campus I' },
  { lat: 16.7589, lng: -93.1534, name: 'Plaza Cristal' },
  { lat: 16.7565, lng: -93.1410, name: 'Rectoría UNICACH' },
  { lat: 16.7547, lng: -93.1235, name: 'Parque de la Marimba' },
  { lat: 16.7516, lng: -93.1161, name: 'Parque Central' },
  { lat: 16.7495, lng: -93.1065, name: 'Parque 5 de Mayo' },
  { lat: 16.7470, lng: -93.0880, name: 'Polyforum Chiapas' },
  { lat: 16.7455, lng: -93.0833, name: 'Diana Cazadora' }
];

const ruta2Points = [
  { lat: 16.7320, lng: -93.1450, name: 'Libramiento Sur Pte' },
  { lat: 16.7350, lng: -93.1280, name: 'Paso a Desnivel San José' },
  { lat: 16.7410, lng: -93.1125, name: 'Mercado de los Ancianos' },
  { lat: 16.7475, lng: -93.1145, name: 'Calle Central Sur' },
  { lat: 16.7516, lng: -93.1161, name: 'Parque Central' },
  { lat: 16.7600, lng: -93.1120, name: 'Teatro de la Ciudad' },
  { lat: 16.7720, lng: -93.1050, name: 'Distribuidor Sumidero' },
  { lat: 16.7840, lng: -93.0980, name: 'Albania Alta / Sumidero' }
];

let step1 = context.get('step1') || 0;
let step2 = context.get('step2') || 0;

const p1 = ruta1Points[step1 % ruta1Points.length];
const p2 = ruta2Points[step2 % ruta2Points.length];

context.set('step1', step1 + 1);
context.set('step2', step2 + 1);

const msg1 = {
  headers: { 'Content-Type': 'application/json' },
  payload: {
    unitId: 'TX-101',
    routeId: 'a0000001-0000-0000-0000-000000000001',
    routeName: 'Ruta 1 - Centro / Terán',
    lat: p1.lat,
    lng: p1.lng,
    speedKmh: Math.floor(Math.random() * 15) + 25,
    timestamp: new Date().toISOString()
  }
};

const msg2 = {
  headers: { 'Content-Type': 'application/json' },
  payload: {
    unitId: 'TX-204',
    routeId: 'a0000002-0000-0000-0000-000000000002',
    routeName: 'Ruta 2 - Sur / Poniente',
    lat: p2.lat,
    lng: p2.lng,
    speedKmh: Math.floor(Math.random() * 12) + 20,
    timestamp: new Date().toISOString()
  }
};

return [[msg1, msg2]];
